/* =========================================================
   รับคำสั่งจากเว็บ → เก็บสถานะ → ส่ง MQTT → ตอบเว็บ → ack
   out1 = mqtt, out2 = http response, out3 = telemetry, out4 = ack
========================================================= */

// sensor group → hardware group + valve
const MAP = {
    group1: { zone: 'sunflower', valveId: 4, targetGroup: 'group4' },
    group2: { zone: 'herb',      valveId: 2, targetGroup: 'group2' },
    group3: { zone: 'sunnhemp',  valveId: 4, targetGroup: 'group4' },
    group4: { zone: 'potted',    valveId: 4, targetGroup: 'group4' },
    group5: { zone: 'rice',      valveId: 3, targetGroup: 'group3' }
};

// sensor group ของแต่ละโซน (ใช้สร้าง valveStatus / pumpStatus)
const ZONES = {
    herb:      'group2',
    rice:      'group5',
    sunnhemp:  'group3',
    sunflower: 'group1',
    potted:    'group4'
};

function buildValveStatus(state) {
    const on = (hw, valve) => Boolean(state[hw] && state[hw][valve]);

    return {
        herb:      { groupId: 'group2', valves: { '2': on('group2', 2) } },
        rice:      { groupId: 'group5', valves: { '3': on('group3', 3) } },
        sunnhemp:  { groupId: 'group3', valves: { '4': on('group4', 4) } },
        sunflower: { groupId: 'group1', valves: { '4': on('group4', 4) } },
        potted:    { groupId: 'group4', valves: { '4': on('group4', 4) } }
    };
}

function buildPumpStatus(state) {
    const on = (hw, valve) => Boolean(state[hw] && state[hw][valve]);

    const out = {};

    for (const [zone, groupId] of Object.entries(ZONES)) {
        const mapping = MAP[groupId];
        out[groupId] = on(mapping.targetGroup, mapping.valveId);
    }

    return out;
}

const body = msg.payload || {};
const sourceGroup = String(body.group_id || '').toLowerCase();
const mapping = MAP[sourceGroup];

if (!mapping) {
    node.status({ fill: 'red', shape: 'ring', text: 'group ไม่ถูกต้อง: ' + sourceGroup });

    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'group_id ไม่ถูกต้อง: ' + sourceGroup };

    return [null, msg, null, null];
}

// request รับได้ทั้ง boolean / "ON" / "OFF" / 1 / 0
const raw = body.request !== undefined ? body.request : body.state;
const state = raw === true || raw === 1 || raw === 'ON' || raw === 'on';

// บันทึกสถานะลง flow context (hardware group → valve → bool)
const states = flow.get('valveStates') || {};
states[mapping.targetGroup] = states[mapping.targetGroup] || {};
states[mapping.targetGroup][mapping.valveId] = state;
flow.set('valveStates', states);

const valveStatus = buildValveStatus(states);
const pumpStatus = buildPumpStatus(states);

node.status({
    fill: state === true ? 'green' : 'grey',
    shape: 'dot',
    text: mapping.zone + ' | Valve ' + mapping.valveId + ' = ' + (state === true ? 'ON' : 'OFF')
});

// 1) MQTT: ใช้ topic เดียวกับที่ Map Zone to Valve อ่านอยู่
const mqttMsg = {
    topic: 'pump/request/' + sourceGroup,
    payload: {
        request: state,
        valveId: mapping.valveId,
        targetGroup: mapping.targetGroup,
        zone: mapping.zone
    },
    qos: 0,
    retain: false
};

// 2) ตอบ HTTP กลับเว็บ (Node-RED เป็นคนตอบ ไม่ใช่ HTTP Response node)
const responseMsg = {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json' },
    payload: {
        ok: true,
        zone: mapping.zone,
        group_id: sourceGroup,
        targetGroup: mapping.targetGroup,
        valve_id: mapping.valveId,
        state: state
    }
};

// 3) รายงานสถานะกลับเว็บ
const telemetryMsg = {
    payload: {
        valveStatus: valveStatus,
        pumpStatus: pumpStatus
    }
};

// 4) ack คำสั่ง (ถ้าเว็บส่ง commandId มา)
const ackMsg = body.commandId
    ? { payload: { commandId: body.commandId, ok: true } }
    : null;

return [mqttMsg, responseMsg, telemetryMsg, ackMsg];

/* รับ { ok:true, commands:[{commandId, zone, group_id, state}] }
   out1 = mqtt, out2 = ack */
const commands = (msg.payload && msg.payload.commands) || [];
const cmd = commands[0];

if (!cmd) return null;

const MAP = {
    group1: { zone: 'sunflower', valveId: 4, targetGroup: 'group4' },
    group2: { zone: 'herb',      valveId: 2, targetGroup: 'group2' },
    group3: { zone: 'sunnhemp',  valveId: 4, targetGroup: 'group4' },
    group4: { zone: 'potted',    valveId: 4, targetGroup: 'group4' },
    group5: { zone: 'rice',      valveId: 3, targetGroup: 'group3' }
};

const mapping = MAP[cmd.group_id];

if (!mapping) {
    node.warn('คำสั่งมี group ที่ไม่รู้จัก: ' + cmd.group_id);

    return [null, { payload: { commandId: cmd.commandId, ok: false, error: 'unknown group_id' } }];
}

flow.set('lastCommand', cmd);

node.status({
    fill: cmd.state ? 'green' : 'grey',
    shape: 'dot',
    text: 'ดึงคำสั่ง: ' + cmd.zone + ' → Valve ' + mapping.valveId
});

return [
    {
        topic: 'pump/request/' + cmd.group_id,
        payload: {
            request: cmd.state === true,
            valveId: mapping.valveId,
            targetGroup: mapping.targetGroup,
            zone: mapping.zone
        },
        qos: 0,
        retain: false
    },
    {
        payload: { commandId: cmd.commandId, ok: true }
    }
];

/* เตรียม POST /api/control/pump/ack */
if (!msg.payload || !msg.payload.commandId) return null;

msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.url = 'https://smart-irrigation-web-beta.vercel.app/api/control/pump/ack';

return msg;

/* สร้าง payload ตามที่เว็บรับ:
   { valveStatus: { zone:{groupId,valves:{"2":true}} }, pumpStatus: { group1:false, ... } }
   อ่านสถานะจาก flow.valveStates ที่ Receive Valve Command เขียนไว้ */
const state = flow.get('valveStates') || {};

const on = (hw, valve) => Boolean(state[hw] && state[hw][valve]);

const valveStatus = {
    herb:      { groupId: 'group2', valves: { '2': on('group2', 2) } },
    rice:      { groupId: 'group5', valves: { '3': on('group3', 3) } },
    sunnhemp:  { groupId: 'group3', valves: { '4': on('group4', 4) } },
    sunflower: { groupId: 'group1', valves: { '4': on('group4', 4) } },
    potted:    { groupId: 'group4', valves: { '4': on('group4', 4) } }
};

const pumpStatus = {
    group1: on('group4', 4), // sunflower
    group2: on('group2', 2), // herb
    group3: on('group4', 4), // sunnhemp
    group4: on('group4', 4), // potted
    group5: on('group3', 3)  // rice
};

node.status({
    fill: Object.values(pumpStatus).some(Boolean) ? 'green' : 'grey',
    shape: 'dot',
    text: 'ส่งสถานะวาล์วแล้ว'
});

msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.url = 'https://smart-irrigation-web-beta.vercel.app/api/sensors/telemetry';
msg.payload = { valveStatus: valveStatus, pumpStatus: pumpStatus };

return msg;
